import java.util.*;

class Solution {
    static int longestUniqueRun(String pages) {
        Map<Character, Integer> lastSeen = new HashMap<>();
        int start = 0, best = 0;
        for (int end = 0; end < pages.length(); end++) {
            char page = pages.charAt(end);
            Integer previous = lastSeen.get(page);
            if (previous != null && previous >= start) start = previous + 1;
            lastSeen.put(page, end);
            best = Math.max(best, end - start + 1);
        }
        return best;
    }
}
